#!/bin/sh -e

# Check MPIRUN - if not set, skip this test
if [ -z "${MPIRUN}" ]; then
    echo "MPIRUN is not set. Skipping MPI test."
    exit 0
fi


mkdir -p read_ctpq_spin_chain
cd read_ctpq_spin_chain

python3 $1/test/MakeListInvTemp.py

cat > stan.in <<EOF
L = 6
model = "SpinGC"
method = "TPQ"
lattice = "chain"
J = 1.0
NumAve = 10
Lanczos_max = 160
EOF

../../src/HPhi -sdry stan.in


cat > calcmod.def <<EOF
#CalcType = 0:Lanczos, 1:TPQCalc, 2:FullDiag, 3:CG, 4:Time-evolution
#CalcModel = 0:Hubbard, 1:Spin, 2:Kondo, 3:HubbardGC, 4:SpinGC, 5:KondoGC
#Restart = 0:None, 1:Save, 2:Restart&Save, 3:Restart
#CalcSpec = 0:None, 1:Normal, 2:No H*Phi, 3:Save, 4:Restart, 5:Restart&Save
CalcType   5
CalcModel   4
ReStart   0
CalcSpec   0
CalcEigenVec   0
InitialVecType   0
InputEigenVec   0
OutputEigenVec   0
InputHam   0
OutputHam   0
OutputExVec   0
EOF

cat > namelist.def <<EOF
ModPara         modpara.def
LocSpin         locspn.def
Trans           trans.def
CoulombInter    coulombinter.def
Hund            hund.def
Exchange        exchange.def
OneBodyG        greenone.def
TwoBodyG        greentwo.def
CalcMod         calcmod.def
PairExcitation  pair.def
SpectrumVec     zvo_eigenvec_0
InvTemp         list_inv_temp.def
EOF

${MPIRUN} ../../src/HPhi -e namelist.def

# Check value

